INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('srs-rice-mill-erp','Rice mill ERP: weighbridge to dispatch',NULL,'Parboiled rice mill & exporter · India','ERP / CRM','Manufacturing','A factory ERP for a parboiled rice mill. Every truck of paddy is weighed at the weighbridge, checked for moisture and quality, approved and posted against purchase orders, then traced through soaking, steaming, drying and milling into graded rice stock and dispatched against sales orders. Fourteen roles, from weighbridge operator to management, each see only their own screens.','Main workflow: Weigh truck → Record quality check → Approve & post → Receive into production → Soak, steam, dry and mill → Grade & store rice → Dispatch against sales order','["Weighbridge register: capture tickets, add the second weighing, and catch duplicate or mismatched slip numbers", "Quality control: unloading and loading checks with moisture and rejection deductions, then head approval and posting", "Purchase and sales orders: balances update automatically as trucks are received and dispatched", "Production traceability: soaking, steaming, drying and milling batches, traced from rice grade back to the truck", "Inventory and dashboards: stock by variety and location, plus live operations and management dashboards"]'::jsonb,'["Next.js 15", "React 19", "TypeScript", "Tailwind CSS 4", "Supabase (Postgres, Auth, RLS)"]'::jsonb,'/demos/srs-erp/','[{"role": "Admin", "login": "admin@example.com", "secret": "Demo@12345"}, {"role": "Management", "login": "management@example.com", "secret": "Demo@12345"}, {"role": "Weighbridge", "login": "weighbridge@example.com", "secret": "Demo@12345"}, {"role": "QC head", "login": "qc.head@example.com", "secret": "Demo@12345"}, {"role": "Production", "login": "production@example.com", "secret": "Demo@12345"}]'::jsonb,'live',true,true,20) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
