INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('everlane-dating-app','Relationship-first dating app',NULL,'Dating start-up · India','Mobile apps','Dating & social','A dating app for Android and iOS built for people who want a real relationship. Members discover profiles, like and match, chat with safety tools, join small group hangouts and build a detailed profile, with a membership plan for premium features.','Main workflow: Open the app → Discover and like profiles → See who liked you → Chat with matches → Join a hangout → Edit your profile','["Discover: profile cards with like, pass and Spark, plus filters for age, distance and who is online now", "Likes you: see who liked you, with an upgrade screen for premium members", "Messages: chat with matches, with tools to report, block or unmatch", "Hangouts: host or join small plans like coffee, dinner or a movie", "Profile and Explore: edit your profile and see people you have crossed paths with"]'::jsonb,'["Flutter (Android & iOS)", "Dart", "NestJS", "Supabase (Postgres, Auth, Storage)"]'::jsonb,'/demos/everlane/','[]'::jsonb,'live',true,true,30) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
