INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('backseat-car-media-app','Car passenger media player app',NULL,'In-house product','Mobile apps','Media & automotive','An iPhone app and web app for car passengers: play your own playlists, switch to a big-button car mode and cast to the car screen or TV. Channels are grouped, searchable and remembered, so you can continue watching where you left off.','Main workflow: Open a playlist → Pick a channel → Watch → Switch to car mode → Cast to the car screen','["Playlists: add a playlist file and browse channels by group", "Car mode: full-screen player with large passenger controls and a channel strip", "Cast to car: guided casting to a car display or TV", "Favourites and resume: star channels, see recently played and continue watching", "Search: find any channel across all playlists"]'::jsonb,'["Swift & SwiftUI (iPhone)", "HTML, CSS & JavaScript (web app)", "IndexedDB"]'::jsonb,'/demos/backseat/','[]'::jsonb,'live',true,true,40) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
