INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('outpost-z-squad-game','Squad survival shooter game',NULL,'In-house product','Custom software','Gaming','A browser game where you lead a squad down a road past zombie hordes to a boss. Walk through maths gates to grow your squad, upgrade weapons, beat a boss at the end of each stage and spend coins on base upgrades. Progress is saved in the browser.','Main workflow: Upgrade at base → Start battle → Steer through gates → Beat the boss → Collect your reward','["Maths gates: walk through +, −, × or ÷ gates to grow or shrink the squad", "Weapon upgrades: destroy barrels to move from pistol up to plasma, or win soldiers and coins", "Boss fights: a boss with its own health bar at the end of every stage", "Base upgrades: spend coins on squad size, firepower and fire rate", "Saved progress: stages, coins and upgrades are kept in the browser"]'::jsonb,'["Next.js 16", "React 19", "TypeScript", "HTML Canvas", "Web Audio"]'::jsonb,'/demos/survival-shooter/','[]'::jsonb,'live',true,true,120) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
