INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('circle-social-app','Circle social media app (Android)',NULL,'Social app prototype · In-house product','Mobile apps','Social media','A native Android social app for sharing photo posts, stories and messages with friends: a home feed with stories, likes and comments, an explore grid, post creation, an activity list, profiles and direct messages. Shown here through screenshots from the app running on Android.','Main workflow: Log in → Browse the feed → Like and comment → Create a post → Message a friend','["Home feed: stories, posts, double-tap to like, comments, share and save", "Explore: search people and browse a grid of posts", "Create post: pick a photo, write a caption and add a location", "Activity: likes, comments, follows and mentions in one list", "Profiles and messages: post grid, saved tab, follow and direct chats"]'::jsonb,'["Kotlin", "Jetpack Compose", "Material 3", "Android"]'::jsonb,NULL,'[]'::jsonb,'none',false,true,60) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
